import{c as a,Q as e,j as r,m as l}from"./chunks/framework.rWdQudnF.js";const _=JSON.parse('{"title":"架构师-备考 案例分析-系统架构设计真题回顾","description":"","frontmatter":{"title":"架构师-备考 案例分析-系统架构设计真题回顾"},"headers":[],"relativePath":"案例分析/系统架构设计真题回顾.md","filePath":"案例分析/系统架构设计真题回顾.md","lastUpdated":null}'),o={name:"案例分析/系统架构设计真题回顾.md"};function i(n,t,s,h,c,p){return e(),r("div",null,[...t[0]||(t[0]=[l('<p>架构的基础知识更新到了 <a href="/arch-exam/综合知识/架构设计/">架构师-备考 架构设计</a>，这里更多是同步过来部分内容（作为案例复习）</p><p>架构风格、质量属性场景判断、场景六要素等</p><h3 id="质量属性" tabindex="-1">质量属性 <a class="header-anchor" href="#质量属性" aria-label="Permalink to &quot;质量属性&quot;">​</a></h3><p>质量属性看一下这个笔记： <a href="/arch-exam/综合知识/架构设计/软件系统的质量属性.html">架构师-备考 架构设计- 软件系统的质量属性</a></p><h3 id="质量属性场景六要素" tabindex="-1">质量属性场景六要素 <a class="header-anchor" href="#质量属性场景六要素" aria-label="Permalink to &quot;质量属性场景六要素&quot;">​</a></h3><blockquote><p>软件系统质量属性（Quality Attribute）是一个系统的可测量或可测试的属性，用来描述系统满足利益相关者需求的程度。</p></blockquote><p><strong>质量属性场景六要素：</strong></p><ol><li><strong>刺激源</strong>（Source）— 谁发出的刺激</li><li><strong>刺激</strong>（Stimulus）— 触发系统的事件</li><li><strong>环境</strong>（Environment）— 事件发生时的条件</li><li><strong>制品</strong>（Artifact）— 被影响的系统组成部分</li><li><strong>响应</strong>（Response）— 系统对刺激的反应行为</li><li><strong>响应度量</strong>（Response Measure）— 可量化的评估指标</li></ol><blockquote><p>简化三要素（场景最小描述）：<strong>刺激、环境、响应</strong></p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260519001012.png" alt="image.png"></p><h3 id="架构风格" tabindex="-1">架构风格 <a class="header-anchor" href="#架构风格" aria-label="Permalink to &quot;架构风格&quot;">​</a></h3><ul><li><a href="/arch-exam/综合知识/架构设计/架构风格与模式.html">架构师-备考 架构设计-架构风格与模式</a> 你直接看一下这个笔记内容</li></ul><h3 id="软件架构评估" tabindex="-1">软件架构评估 <a class="header-anchor" href="#软件架构评估" aria-label="Permalink to &quot;软件架构评估&quot;">​</a></h3><p>看一下这个 <a href="/arch-exam/综合知识/架构设计/软件架构评估.html">架构师-备考 架构设计-软件架构评估</a></p><p>常用评估方法：</p><ul><li>基于场景的架构分析方法 SAAM</li><li>架构权衡分析方法 ATAM <ul><li><strong>采用效用树(Utility tree)这一工具来对质量属性进行分类和优先级排序</strong>。效用树的结构包括：树根-质量属性-属性分类-质量属性场景</li></ul></li><li>成本效益分析法 CBAM</li></ul><hr>',17)])])}const d=a(o,[["render",i]]);export{_ as __pageData,d as default};
